  "repair_strategy": "Modify the Document focus handling in checkFocusIn to detect when the mostRecentlyFocusedNode has become detached (indicating the focused element was removed), and proactively restore focus to the trap's initial focus node instead of returning early.",
  "edits": [
    {
      "path": "index.js",
      "sha256": "17ff10072d68a0aabb1e15fdc42b3a1dee1774dc2ced6facc4753e9a5ae89f90",
      "before": "    // In Firefox when you Tab out of an iframe the Document is briefly focused.
    if (targetContained || target instanceof Document) {
      if (targetContained) {
        state.mostRecentlyFocusedNode = target;
      }
      state.recentNavEvent = undefined; // clear
      return;
    }",
      "after": "    // In Firefox when you Tab out of an iframe the Document is briefly focused.
    // But if the previously focused node in the trap was removed, we need to restore focus.
    if (targetContained || target instanceof Document) {
      if (targetContained) {
        state.mostRecentlyFocusedNode = target;
      } else if (target instanceof Document) {
        // Focus moved to Document. If the MRU node was in the trap and is now detached,
        // restore focus to the initial focus node.
        if (
          state.mostRecentlyFocusedNode &&
          !doc.contains(state.mostRecentlyFocusedNode)
        ) {
          state.mostRecentlyFocusedNode = null;
          tryFocus(getInitialFocusNode());
        }
      }
      state.recentNavEvent = undefined; // clear
      return;
    }"
    }
  ],
  "expected_accessibility_effect": "Keyboard focus remains trapped inside the dialog after removing an item, preserving tab order and preventing focus loss to background elements.",
  "functional_risks": [
    "The Document focus check may trigger on legitimate temporary Document focus (Firefox iframe), causing unnecessary focus restoration. However, the detached-node check mitigates this."
  ],
  "verification_requirements": [
    "After pressing Enter on the remove button of an item, the count updates and focus stays inside the basket (#basket:focus-within is true).",
    "Tab navigation continues to wrap correctly within the dialog after item removal."
  ]
}

